import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CDS G/H (Day 1) - Calamari Development","description":"","frontmatter":{"title":"CDS G/H (Day 1) - Calamari Development","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph","Calamari","Distributed Storage","Development","Open Source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_Calamari_Development.md","filePath":"posts/2014/CDS_G_H_Day_1_-_Calamari_Development.md","lastUpdated":1780459816000}'),o={name:"posts/2014/CDS_G_H_Day_1_-_Calamari_Development.md"};function r(p,l,n,s,_,g){return i(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Calamari 开发讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： John Gregor, Sage, Patrick等</p><p><strong>会议内容</strong>：</p><p><strong>一、Calamari 开发计划</strong></p><ol><li><p><strong>Crush 管理功能</strong>：</p><ul><li>高优先级功能，即将加入 Calamari REST API。</li><li>目的：支持 Erasure Code 池和 Cache Tiering 等特性。</li><li>主要工作： <ul><li>实现 Crush Map 的 CRUD 操作。</li><li>将 OSD 和主机映射到 Crush 节点。</li><li>处理 Ceph 配置文件中的 Crush Location 问题。</li></ul></li></ul></li><li><p><strong>其他工作</strong>：</p><ul><li>清理使用 Salt 私有接口的代码。</li><li>将 Diamond 和 Graphite 的分支合并到上游。</li><li>改进打包方式，简化前端构建过程。</li><li>移除 DoSulu 插件管理器。</li></ul></li></ol><p><strong>二、社区合作</strong></p><ol><li><p><strong>Dashing Ceph 和 Sef-Dash</strong>：</p><ul><li>讨论了将社区项目代码整合到 Calamari 的可能性。</li><li>目前 UI 开发资源有限，优先考虑将社区贡献的 UI 设计理念整合到 Calamari。</li></ul></li><li><p><strong>Ink Scope</strong>：</p><ul><li>讨论了 Ink Scope 项目与 Calamari 的合作可能性。</li><li>鼓励社区成员参与 UI 开发。</li></ul></li></ol><p><strong>三、其他事项</strong></p><ol><li><p><strong>文档聚合</strong>：</p><ul><li>讨论了将文档聚合到 ceph.com 的可能性。</li></ul></li><li><p><strong>Ceph 官网</strong>：</p><ul><li>讨论了 Ceph 官网的重构计划。</li></ul></li></ol><p><strong>行动计划</strong>：</p><ol><li>John Gregor 和 Sage 负责推进 Crush 管理功能的开发。</li><li>Sage 负责清理使用 Salt 私有接口的代码。</li><li>Sage 负责将 Diamond 和 Graphite 的分支合并到上游。</li><li>Sage 负责改进打包方式，简化前端构建过程。</li><li>Sage 负责移除 DoSulu 插件管理器。</li><li>社区成员参与 UI 开发。</li><li>讨论文档聚合和 Ceph 官网的重构计划。</li></ol><p><strong>会议总结</strong>：</p><p>本次会议讨论了 Calamari 的开发计划、社区合作以及其他相关事项。会议明确了下一步的工作计划和行动计划，为 Calamari 的发展奠定了基础。</p>',15)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
